106	{
107	    if (!predicate)
108	    {
109	        rpn.emplace_back(RPNElement::FUNCTION_UNKNOWN);
110	        return;
111	    }
112	
113	    const auto & settings = context_->getSettingsRef();
114	    static constexpr auto cache_policy = "SLRU";
115	    size_t max_memory_usage = std::min(settings[Setting::max_memory_usage] / 10ULL, 100ULL * 1024 * 1024);
116	
117	    /// If usage of global text index caches is disabled, create local
118	    /// one to share them between threads that read the same data parts.
119	    if (settings[Setting::use_text_index_tokens_cache])
120	        tokens_cache = context_->getTextIndexTokensCache();
121	    else
122	        tokens_cache = std::make_shared<TextIndexTokensCache>(cache_policy, max_memory_usage, 0, 1.0);
123	
124	    if (settings[Setting::use_text_index_header_cache])
125	        header_cache = context_->getTextIndexHeaderCache();
126	    else
127	        header_cache = std::make_shared<TextIndexHeaderCache>(cache_policy, max_memory_usage, 0, 1.0);
128	
129	    if (settings[Setting::use_text_index_postings_cache])
130	        postings_cache = context_->getTextIndexPostingsCache();
131	    else
132	        postings_cache = std::make_shared<TextIndexPostingsCache>(cache_policy, max_memory_usage, 0, 1.0);
133	
134	    rpn = std::move(RPNBuilder<RPNElement>(
135	        predicate,
136	        context_,
137	        [&](const RPNBuilderTreeNode & node, RPNElement & out)
138	        {
139	            return this->traverseAtomNode(node, out);
140	        }).extractRPN());
141	
142	    NameSet all_search_tokens_set;
143	
144	    for (const auto & element : rpn)
145	    {
146	        for (const auto & search_query : element.text_search_queries)
147	        {
148	            all_search_tokens_set.insert(search_query->tokens.begin(), search_query->tokens.end());
149	            all_search_queries[search_query->getHash().get128()] = search_query;
150	
151	            for (const auto & pattern : search_query->patterns)
152	                all_search_patterns.push_back(&pattern);
153	        }
154	
155	        if (requiresReadingAllTokens(element))
156	            global_search_mode = TextSearchMode::Any;
157	    }
158	
159	    all_search_tokens = Names(all_search_tokens_set.begin(), all_search_tokens_set.end());
160	    std::ranges::sort(all_search_tokens); /// Technically not necessary but leads to nicer read patterns on sorted dictionary blocks
